{"hash":"1a5891548a6b6d24bec4bbfc349330105d41842c3230b370df465b01da6113f5","kind":"tool_completed","payload":{"name":"asset.read","result":{"asset_id":"research-facts","sha256":"e65d08b40ec3b8bdb8411cf95a69cd5fcbb67ce34c327be9f3cac721eb302a95","text":"{\"bibliography\":[{\"citation_id\":\"source-study\",\"url\":\"https://arxiv.org/abs/2410.03263v1\",\"usage\":\"Source of fixed facts, not prose to reproduce\",\"version\":\"v1\"}],\"evaluation_facts\":[{\"fact\":\"UTKFace target images use 13 corruption types at severity 5. Predict age; R2 is higher-better and may be negative.\",\"id\":\"E1\",\"source_locator\":\"S4.SS1 and S4.T4\"},{\"fact\":\"Source is the unadapted comparator. Oracle has target-label access and is not a same-information competitor.\",\"id\":\"E2\",\"source_locator\":\"S4.SS2\"},{\"fact\":\"The supplied cells are rounded author-reported aggregate values, not independent experimental repetitions.\",\"id\":\"E3\",\"source_locator\":\"S4.T4; input construction boundary\"}],\"method_facts\":[{\"fact\":\"A source-trained feature extractor feeds a fixed linear regression head w.T z + b.\",\"id\":\"M1\",\"source_locator\":\"S3.SS2\"},{\"fact\":\"Source feature covariance supplies leading eigenvectors V and positive eigenvalues lambda; project centered features as V(z-mu_source).\",\"id\":\"M2\",\"source_locator\":\"S3.SS2\"},{\"fact\":\"Per-axis target batch means and variances are aligned to source moments (0, lambda) with a weighted symmetric Gaussian KL objective; alpha_d = 1 + abs(w.T v_d).\",\"id\":\"M3\",\"source_locator\":\"S3.SS2\"},{\"fact\":\"Source data are unavailable during target adaptation; source statistics were obtained beforehand. Target labels are not adaptation inputs.\",\"id\":\"M4\",\"source_locator\":\"S3.SS1 and S3.SS2\"},{\"fact\":\"Adaptation updates only the feature extractor's normalization affine scale and shift parameters (gamma, beta); other model parameters, including the regression head, remain fixed.\",\"id\":\"M5\",\"source_locator\":\"S3.SS2 immediately after Eq.8\"}],\"scope\":\"Regression test-time adaptation; the numeric evidence supplied here concerns corrupted UTKFace age prediction only.\",\"unknown_or_excluded\":[{\"fact\":\"Per-run observations and sampling uncertainty are not supplied.\",\"id\":\"U1\",\"source_locator\":\"public input construction boundary, not a claim about all author assets\"},{\"fact\":\"No supplied compute measurements, independent reproduction or test of causality.\",\"id\":\"U2\",\"source_locator\":\"public input construction boundary, not a claim about all author assets\"},{\"fact\":\"No full algorithm implementation or claim of licensed reuse of the author's proprietary repository.\",\"id\":\"U3\",\"source_locator\":\"public input construction boundary, not a claim about all author assets\"},{\"fact\":\"No other dataset table is included; do not import inconsistent summaries from elsewhere.\",\"id\":\"U4\",\"source_locator\":\"public input construction boundary, not a claim about all author assets\"}]}\n"},"result_hash":"8917e6ed123bee2b919bfcb3c09539dc2cb225f9ff5f3906ac49494c857b806f"},"previous_hash":"572c36d6ca5f3c734dc061a1a0f09906ab17c5e40fb692a62036c2fd1a22c67b","sequence":5,"time_utc":"2026-09-23T05:58:27.770479+00:00"}
